const PARTS = [
  { name: 'jan', from: 1,  to: 31 },
  { name: 'feb', from: 31, to: 59 },
  { name: 'mar', from: 59, to: 90 },
];
function partitionFor(day) {
  for (const p of PARTS) {
    if (day >= p.from && day <= p.to) return p.name; // BUG: upper bound inclusive
  }
  return null;
}

